patch:
diff --git a/packages/svelte/src/compiler/phases/2-analyze/visitors/Attribute.js b/packages/svelte/src/compiler/phases/2-analyze/visitors/Attribute.js
index 773aa59..62ac856 100644
--- a/packages/svelte/src/compiler/phases/2-analyze/visitors/Attribute.js
+++ b/packages/svelte/src/compiler/phases/2-analyze/visitors/Attribute.js
@@ -193,7 +193,14 @@ function get_delegated_event(event_name, handler, context) {
 		}

 		// If we are referencing a binding that is shadowed in another scope then bail out.
-		if (local_binding !== null && binding !== null && local_binding.node !== binding.node) {
+		// Unless the binding is declared within the function we're hoisting, in which
+		// case the shadowing is local to the function and hoisting is safe.
+		if (
+			local_binding !== null &&
+			binding !== null &&
+			local_binding.node !== binding.node &&
+			!(binding.node.start > target_function.start && binding.node.end < target_function.end)
+		) {
 			return unhoisted;
 		}
